package java.util.concurrent.atomic;
public class AtomicIntegerArray implements java.io.Serializable {private final int[] values;public AtomicIntegerArray(int n){values=new int[n];}public AtomicIntegerArray(int[] a){values=new int[a.length];System.arraycopy(a,0,values,0,a.length);}public int length(){return values.length;}public synchronized int get(int i){return values[i];}public synchronized void set(int i,int v){values[i]=v;}public void lazySet(int i,int v){set(i,v);}public synchronized int getAndSet(int i,int v){int o=values[i];values[i]=v;return o;}public synchronized boolean compareAndSet(int i,int e,int v){if(values[i]!=e)return false;values[i]=v;return true;}public boolean weakCompareAndSet(int i,int e,int v){return compareAndSet(i,e,v);}public synchronized int getAndIncrement(int i){return values[i]++;}public synchronized int getAndDecrement(int i){return values[i]--;}public synchronized int getAndAdd(int i,int d){int v=values[i];values[i]+=d;return v;}public synchronized int incrementAndGet(int i){return ++values[i];}public synchronized int decrementAndGet(int i){return --values[i];}public synchronized int addAndGet(int i,int d){return values[i]+=d;}public String toString(){StringBuilder b=new StringBuilder("[");for(int i=0;i<length();i++){if(i>0)b.append(", ");b.append(values[i]);}return b.append(']').toString();}}
